def json_convertor_default(default_mapping=None):
    if default_mapping:
        JSON_CONVERTOR.update(default_mapping)
    return JSON_CONVERTOR


def json_dumps(item, default_mapping=None, force_use_builtin_json: bool=
    False, **kwargs):
    if orjson and not force_use_builtin_json:
        return orjson.dumps(item, option=orjson.OPT_NON_STR_KEYS)
    else:
        return json.dumps(item, default=json_convertor_default(default_mapping), **kwargs)


def to_json(self, default_mapping: Optional[dict]=None,
    force_use_builtin_json=False, **kwargs):
    dic = self.to_dict(view_override=TEXT_VIEW)
    return json_dumps(
        dic,
        default_mapping=default_mapping,
        force_use_builtin_json=force_use_builtin_json,
        **kwargs,
    )


def to_dict(self, view_override=None):
    view = view_override if view_override else self.view
    return dict(self._get_view_results(view))
